        Check(DecimalEditing.Format("3",2)=="3.00"&&DecimalEditing.Format("0.015",3)=="0.015","decimal display remains fixed while commission precision is preserved");
        var time=new DateTimeOffset(2026,11,6,9,0,0,TimeSpan.FromHours(9));var bars=Enumerable.Range(0,120).Select(n=>new PriceBar(time.AddMinutes(n),100+n,102+n,99+n,101+n,1000)).ToArray();var fills=Enumerable.Range(0,100).Select(n=>new TradeMarker("fixture-"+n,"KRX:005930",time.AddMinutes(n),n%2==0,1,101+n,"SYNTHETIC",TradeNumber:n/2+1,RealizedPnl:n%2==0?null:2)).ToArray();
