        Check(!badges.SelectMany((b,i)=>badges.Skip(i+1).Select(other=>b.Bounds.Intersects(other.Bounds))).Any(overlap=>overlap),"dense execution captions do not overlap each other after grouping and placement");
        TradeMarker? picked=null;chart.TradeSelected+=marker=>picked=marker;var markerPixel=plot.Plot.GetPixel(new ScottPlot.Coordinates(30,131));var markerPoint=plot.TranslatePoint(new(markerPixel.X,markerPixel.Y),window)!.Value;window.MouseDown(markerPoint,MouseButton.Left);window.MouseUp(markerPoint,MouseButton.Left);Dispatcher.UIThread.RunJobs();Check(picked?.Id==fills[30].Id,"one click on a traded candle selects its original execution even with merged labels");
        picked=null;ClickAt(window,badges[0],.5);Check(picked?.Id==((ChartMarkerGroup)badges[0].Tag!).Trades[0].Id,"one click on a native caption badge selects its own original execution without a double click");
