        window.MouseWheel(origin,new Vector(0,2));Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();var zoom=plot.Plot.Axes.GetLimits();Check(zoom.Right-zoom.Left<limits.Right-limits.Left,"mouse wheel actually zooms the installed ScottPlot Avalonia input pipeline");
        var anchorAfter=plot.Plot.GetCoordinates(new ScottPlot.Pixel((float)pixel.X,(float)pixel.Y)).X;Check(Math.Abs(anchorBefore-anchorAfter)<(limits.Right-limits.Left)*.02,"wheel zoom remains anchored at the cursor rather than at the latest candle");
        var before=plot.Plot.Axes.GetLimits();window.MouseDown(origin,MouseButton.Left);window.MouseMove(origin+new Vector(100,0),RawInputModifiers.LeftMouseButton);window.MouseUp(origin+new Vector(100,0),MouseButton.Left);Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();var after=plot.Plot.Axes.GetLimits();Check(after.Left!=before.Left,"dragging from inside the chart pans continuously instead of requiring an edge click");
        var performance=System.Diagnostics.Stopwatch.StartNew();chart.OverviewNavigation=true;chart.Bars=Enumerable.Range(0,10000).Select(n=>new PriceBar(time.AddMinutes(n),100+n,102+n,99+n,101+n,1000)).ToArray();Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();var overviewMs=performance.Elapsed.TotalMilliseconds;var whole=plot.Plot.Axes.GetLimits();var centerPixel=plot.Plot.GetPixel(new ScottPlot.Coordinates((whole.Left+whole.Right)/2,(whole.Bottom+whole.Top)/2));var centerPoint=plot.TranslatePoint(new(centerPixel.X,centerPixel.Y),window)!.Value;window.MouseWheel(centerPoint,new Vector(0,3));Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();Check(!chart.DetailActive&&plot.Plot.Axes.GetLimits().Left==whole.Left,"large screening overview shows the entire period and holds wheel navigation until right click");
        performance.Restart();window.MouseDown(centerPoint,MouseButton.Right);window.MouseUp(centerPoint,MouseButton.Right);for(var i=0;i<3;i++){Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();}var detailLimits=plot.Plot.Axes.GetLimits();var detailMs=performance.Elapsed.TotalMilliseconds;Check(chart.DetailActive&&detailLimits.Right-detailLimits.Left<(whole.Right-whole.Left)/2,"right click opens a bounded candle window around the clicked time");
        window.MouseWheel(centerPoint,new Vector(0,-20));for(var i=0;i<3;i++){Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();}var bounded=plot.Plot.Axes.GetLimits();Check(bounded.Right-bounded.Left<=(detailLimits.Right-detailLimits.Left)*1.0001,"detail wheel zoom cannot zoom out beyond its initial right-click range");window.MouseDown(centerPoint,MouseButton.Right);window.MouseUp(centerPoint,MouseButton.Right);Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();Check(!chart.DetailActive,"second right click returns to the locked full-period overview");File.WriteAllText(Path.Combine(output,"candle-navigation-performance.json"),Serialization.Pack(new{OverviewCandles=10000,DetailCandles=StockChart.DetailBarCount,OverviewMs=overviewMs,DetailMs=detailMs,Environment="Windows Avalonia Headless synthetic; Mac not measured"}));
        chart.Bars=[];Dispatcher.UIThread.RunJobs();Check(chart.RenderedCandles==0&&chart.RenderedMarkers==0&&tradeLayer.Children.Count==0,"an empty or changed chart clears previous candles and execution labels");window.Close();
        using var services=new AppServices(Path.Combine(output,"history-isolated",Guid.NewGuid().ToString("N")),new MarketFixture());using var model=new MainViewModel(services);var main=new MainWindow{DataContext=model};main.Show();model.SearchCommand.Execute(null);Pump(()=>!model.Busy&&model.SelectedStock!=null);model.Strategies.Selected=StrategyDiagnosticPreset.HoldOneDayName;model.Recurring.To=DateTime.Today.AddDays(-1);model.Recurring.Run.Execute(null);Pump(()=>model.History.Any(h=>h.Entry.Kind==DesktopRunKind.Recurring));foreach(var popup in main.OwnedWindows.ToArray())popup.Close();model.SelectedHistory=model.History.Single();model.OpenHistoryCommand.Execute(null);Pump(()=>main.OwnedWindows.Any(w=>w.Content is RecurringResultPanel));Check(true,"recurring history reopens its frozen result and price bars from a lightweight index");foreach(var popup in main.OwnedWindows.ToArray())popup.Close();
        model.Screening.ShowAll=true;model.Screening.To=DateTime.Today.AddDays(-1);model.Screening.Start.Execute(null);Pump(()=>!model.Screening.Busy&&model.History.Any(h=>h.Entry.Kind==DesktopRunKind.Screening));model.SelectedHistory=model.History.Single(h=>h.Entry.Kind==DesktopRunKind.Screening);model.OpenHistoryCommand.Execute(null);Pump(()=>main.OwnedWindows.Any(w=>w.Content is ScreeningPanel));Check(((ScreeningPanel)main.OwnedWindows.Single(w=>w.Content is ScreeningPanel).Content!).DataContext is ScreeningWorkspace{ReadOnly:true},"stored screening opens read-only with its original configuration and period");main.Close();
        var paused=new MarketFixture{UniversePause=new(TaskCreationOptions.RunContinuationsAsynchronously)};using var frozenServices=new AppServices(Path.Combine(output,"frozen-isolated",Guid.NewGuid().ToString("N")),paused);using var frozen=new MainViewModel(frozenServices);frozen.Strategies.Selected=StrategyDiagnosticPreset.HoldOneDayName;frozen.Screening.Market="코스피";frozen.Screening.ShowAll=true;frozen.Screening.To=DateTime.Today.AddDays(-1);frozen.Screening.Start.Execute(null);Pump(()=>frozen.Screening.Busy);frozen.Strategies.Selected="기본";frozen.Screening.Market="코스닥";paused.UniversePause.TrySetResult();Pump(()=>!frozen.Screening.Busy);Check(frozen.Screening.Snapshot is {Results.Length:1} snapshot&&snapshot.StrategyName==StrategyDiagnosticPreset.HoldOneDayName&&snapshot.Targets[0].Board=="KOSPI","strategy name/configuration and target market freeze before slow universe retrieval");
        Check(AsyncCommand.FailureCount==0,"all desktop scenarios finish without an unhandled command failure");
